import Foundation
import Combine
import AirliftFFI

/// Runs Airlift's RPPairing host and persists the pairing record generated by iOS.
@MainActor
final class PairingController: ObservableObject {
    static let shared = PairingController()

    private let hostName = "Primitive"
    // Airlift uses this host model for the Developer Mode pairing flow.
    private let hostModel = "Mac17,7"
    private let bindAddress = "0.0.0.0"
    private let localNetwork = LocalNetworkAuthorization()
    private let keepAlive = KeepAlive()
    private var netService: NetService?
    private var pairContinuation: CheckedContinuation<String, Error>?

    @Published private(set) var isRunning = false
    @Published private(set) var pairingPIN: String?
    @Published private(set) var pairingStatus = "Ready to pair."

    private static let altIRKKey = "primitive.pairing.host.altirk"
    nonisolated(unsafe) private static var storedAltIRK: String {
        get { UserDefaults.standard.string(forKey: altIRKKey) ?? "" }
        set { UserDefaults.standard.set(newValue, forKey: altIRKKey) }
    }

    enum PairingError: LocalizedError {
        case busy
        case emptyRecord
        case failed(String)

        var errorDescription: String? {
            switch self {
            case .busy:
                return "A pairing request is already running."
            case .emptyRecord:
                return "iOS completed the request, but Airlift did not produce a pairing record."
            case .failed(let message):
                return message
            }
        }
    }

    /// Starts the native pairing host, waits for iOS approval, and stores the resulting plist.
    @discardableResult
    func startAndStore() async throws -> URL {
        guard !isRunning else { throw PairingError.busy }
        let outputURL = try PairingRecordStore.preparePairingOutputURL()
        defer { try? FileManager.default.removeItem(at: outputURL) }

        let generatedPath = try await startAndWait(outputPath: outputURL.path)
        let generatedURL = URL(fileURLWithPath: generatedPath)
        let data = try Data(contentsOf: generatedURL)
        guard !data.isEmpty else { throw PairingError.emptyRecord }

        let savedURL = try PairingRecordStore.save(data, originalName: "primitive-pairing.plist")
        pairingStatus = "Pairing record saved securely."
        return savedURL
    }

    private func startAndWait(outputPath: String) async throws -> String {
        guard !isRunning else { throw PairingError.busy }

        return try await withCheckedThrowingContinuation { continuation in
            pairContinuation = continuation
            isRunning = true
            pairingPIN = nil
            pairingStatus = "Requesting Local Network access…"

            Task { @MainActor in
                _ = await localNetwork.request()
                guard isRunning else { return }
                keepAlive.startAudio()
                pairingStatus = "Waiting for the iOS pairing request…"
                runHost(outputPath: outputPath)
            }
        }
    }

    private func runHost(outputPath: String) {
        let bind = bindAddress
        let name = hostName
        let model = hostModel
        let altIRK = Self.storedAltIRK
        nonisolated(unsafe) let context = UnsafeMutableRawPointer(
            Unmanaged.passRetained(self).toOpaque()
        )

        DispatchQueue.global(qos: .userInitiated).async {
            var result = ALPairResult()
            let returnCode = bind.withCString { bindCString in
                name.withCString { nameCString in
                    model.withCString { modelCString in
                        outputPath.withCString { outputCString in
                            altIRK.withCString { irkCString in
                                al_pairing_run_host(
                                    bindCString,
                                    0,
                                    nameCString,
                                    modelCString,
                                    outputCString,
                                    irkCString,
                                    pairReadyCallback,
                                    pairPinCallback,
                                    context,
                                    &result
                                )
                            }
                        }
                    }
                }
            }

            let outcome: Result<String, Error>
            if returnCode == 0 {
                let issuedAltIRK = cString(result.host_alt_irk_hex)
                if !issuedAltIRK.isEmpty {
                    Self.storedAltIRK = issuedAltIRK
                }
                let path = cString(result.pairing_file_path)
                outcome = .success(path.isEmpty ? outputPath : path)
            } else {
                let message = cString(result.error)
                outcome = .failure(PairingError.failed(
                    message.isEmpty ? "Airlift pairing failed (code \(returnCode))." : message
                ))
            }
            al_pairing_result_free(&result)

            DispatchQueue.main.async {
                let controller = Unmanaged<PairingController>.fromOpaque(context).takeUnretainedValue()
                controller.finish(outcome)
                Unmanaged<PairingController>.fromOpaque(context).release()
            }
        }
    }

    private func finish(_ outcome: Result<String, Error>) {
        netService?.stop()
        netService = nil
        isRunning = false
        pairingPIN = nil
        DispatchQueue.main.asyncAfter(deadline: .now() + 5) { [weak self] in
            self?.keepAlive.stopAll()
        }

        switch outcome {
        case .success(let path):
            pairingStatus = "Pairing completed. Saving the pairing record…"
            pairContinuation?.resume(returning: path)
            pairContinuation = nil
        case .failure(let error):
            pairingStatus = "Pairing failed: \(error.localizedDescription)"
            pairContinuation?.resume(throwing: error)
            pairContinuation = nil
        }
    }

    fileprivate func startAdvertising(serviceID: String, port: UInt16, txt: [String: Data]) {
        netService?.stop()
        let service = NetService(
            domain: "",
            type: "_remotepairing-pairable-host._tcp.",
            name: serviceID,
            port: Int32(port)
        )
        service.setTXTRecord(NetService.data(fromTXTRecord: txt))
        service.publish()
        netService = service
        pairingStatus = "Pairing service advertised. Open Developer Mode in Settings."
    }

    fileprivate func presentPIN(_ pin: String) {
        pairingPIN = pin
        pairingStatus = "Enter the six-digit PIN in Settings → Privacy & Security → Developer Mode → Pair with Primitive."
    }
}

private let pairReadyCallback: ALPairReadyCb = { context, serviceID, port, keys, values, count in
    guard let context, let serviceID else { return }
    let controller = Unmanaged<PairingController>.fromOpaque(context).takeUnretainedValue()
    let identifier = String(cString: serviceID)
    var txt: [String: Data] = [:]

    if let keys, let values {
        for index in 0..<Int(count) {
            guard let key = keys[index], let value = values[index] else { continue }
            txt[String(cString: key)] = Data(String(cString: value).utf8)
        }
    }

    DispatchQueue.main.async {
        controller.startAdvertising(serviceID: identifier, port: port, txt: txt)
    }
}

private let pairPinCallback: ALPairPinCb = { pin, context in
    guard let context, let pin else { return }
    let controller = Unmanaged<PairingController>.fromOpaque(context).takeUnretainedValue()
    let value = String(cString: pin)
    DispatchQueue.main.async {
        controller.presentPIN(value)
    }
}

private func cString(_ pointer: UnsafeMutablePointer<CChar>?) -> String {
    guard let pointer else { return "" }
    return String(cString: pointer)
}
